package com.doudou.wxq;
import org.json.*;import java.nio.file.*;import java.util.regex.*;
public final class PrepareWorkshop{public static void main(String[] args)throws Exception{Path path=Paths.get(args[0]);String s=new String(Files.readAllBytes(path),"UTF-8"),build=args[1];JSONObject data=WorkshopData.extract(s,build);StringBuilder patched=new StringBuilder();int last=0;Matcher m=Pattern.compile("(?:\\b(?:const|let|var)\\s+|,)([A-Za-z_$][\\w$]*)\\s*=\\s*(\\[\\{id:)").matcher(s);while(m.find()){try{JsDataReader reader=new JsDataReader(s,m.start(2));JSONArray a=(JSONArray)reader.read();String key=WorkshopData.key(a.getJSONObject(0));if(key.isEmpty())continue;patched.append(s,last,m.start(2)).append("window.__WXQ_DATA__.arrays[").append(JSONObject.quote(key)).append("]");last=reader.position();}catch(Exception ignored){}}patched.append(s.substring(last));Files.write(path,patched.toString().getBytes("UTF-8"));Files.write(path.getParent().getParent().resolve("library-data.json"),data.toString().getBytes("UTF-8"));System.out.println(data.getJSONObject("arrays").keySet());}}
